do $$declare it uuid:='97000000-0000-0000-0000-000000000001';g uuid:='83000000-0000-0000-0000-000000000001';m uuid:='83000000-0000-0000-0000-000000000002';v public.garage_vehicles;d public.garage_departures;c public.vehicle_maintenance_cases;p uuid;n bigint;begin
 insert into auth.users(id,email)values(it,'policy-it@x.iq');insert into public.user_roles(user_id,role)values(it,'it_admin');select id into p from public.notification_workflow_policies where sector_id is null and vehicle_category is null;
 perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',it::text,false);perform public.notification_workflow_policy_save(p,null,null,'approval_required',true,true,array['central_garage_officer'],true,false,false,10,'اختبار الموافقة');select count(*)into n from public.notification_workflow_policies_list()where id=p and mode='approval_required';if n<>1 then raise exception'POLICY_SAVE_FAIL';end if;begin perform public.notification_workflow_policy_delete(p);raise exception'DEFAULT_POLICY_DELETE_ACCEPTED';exception when others then if sqlerrm='DEFAULT_POLICY_DELETE_ACCEPTED'then raise;end if;if sqlerrm not like'%WORKFLOW_DEFAULT_POLICY_REQUIRED%'then raise;end if;end;
 perform set_config('request.jwt.claim.sub',g::text,false);v:=public.garage_add_vehicle('آلية سياسة','DB-POLICY','P-POLICY','C-POLICY',g::text||'/policy.webp','morning','سائق سياسة',5::smallint);d:=public.garage_record_shift_departure(v.id,'morning',null);perform set_config('request.jwt.claim.sub',m::text,false);d:=public.sector_confirm_vehicle_arrival(d.id,'وصلت للموقع');c:=public.sector_send_vehicle_to_maintenance(d.id,'فحص منظومة الفرامل','urgent','تحتاج مراجعة الكراج');if c.garage_decision_status<>'awaiting_approval'then raise exception'APPROVAL_POLICY_NOT_APPLIED';end if;select count(*)into n from public.vehicle_trip_legs where departure_id=d.id and arrived_at is null;if n<>0 then raise exception'VEHICLE_MOVED_BEFORE_APPROVAL';end if;
 perform set_config('request.jwt.claim.sub',g::text,false);select count(*)into n from public.notifications where entity_id=c.id and not push_allowed and not sound_allowed;if n<>1 then raise exception'POLICY_CHANNELS_NOT_APPLIED';end if;select count(*)into n from public.garage_maintenance_coordination()where case_id=c.id and decision_status='awaiting_approval';if n<>1 then raise exception'GARAGE_COORDINATION_QUEUE_FAIL';end if;execute'reset role';update public.vehicle_maintenance_cases set reported_at=now()-interval'11 minutes'where id=c.id;perform set_config('role','service_role',false);perform set_config('request.jwt.claims','{"role":"service_role"}',false);perform public.notification_evaluate_workflow_escalations();execute'reset role';select count(*)into n from public.notifications where user_id=it and entity_id=c.id and priority='critical';if n<>1 then raise exception'WORKFLOW_ESCALATION_FAIL';end if;perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',g::text,false);c:=public.garage_decide_maintenance_dispatch(c.id,'approve','تم التنسيق مع الصيانة');if c.garage_decision_status<>'approved'then raise exception'GARAGE_APPROVAL_FAIL';end if;select count(*)into n from public.vehicle_trip_legs where departure_id=d.id and destination_type='maintenance'and arrived_at is null;if n<>1 then raise exception'VEHICLE_NOT_RELEASED_AFTER_APPROVAL';end if;
 perform set_config('request.jwt.claim.sub',m::text,false);if public.sector_trip_maintenance_state(d.id)->>'decision_status'<>'approved'then raise exception'MANAGER_MAINTENANCE_STATE_FAIL';end if;
 raise notice'✅ سياسات الانطلاق: الإدارة/منع الحذف/انتظار الموافقة/قرار الكراج/تحرير الحركة ناجحة';end$$;
